// Client Insights job runner — Supabase Edge Function (Deno).
//
// GENERATED FILE. Edit scripts/job/template.ts (and src/services/researchPipeline.ts, src/lib/website.ts) and run
// `npm run build:job-function`; do not edit this file by hand.
//
// What it does: runs the same Client Insights research pipeline the browser runs, on the server, and emails the person
// who asked when it is done. An edge function lives at most about 150 seconds, a report takes 5-7 minutes, so the job
// runs in slices:
//
//   * Every research call the pipeline makes is journalled (client_insight_steps), keyed by a hash of the request.
//   * A slice replays the pipeline: calls already in the journal return instantly, new calls start for ~40 seconds,
//     in-flight calls are allowed to finish, then the slice saves and starts the next one (the function calls itself).
//   * A cron job calls `resume` every 2 minutes and restarts any job whose slice died.
//
// Routes (POST, JSON body with `action`):
//   start   browser, signed-in user's token. Creates the job for the token's own toptal.com address.
//   run     internal (x-job-secret). Runs one slice of one job.
//   resume  internal (x-job-secret), from cron. Restarts stalled jobs, retries unsent emails, purges expired rows.
//
// Secrets: JOB_SECRET. Optional email: APPS_SCRIPT_URL, APPS_SCRIPT_SECRET, APP_URL (without them nothing is emailed). SUPABASE_URL, SUPABASE_ANON_KEY and
// SUPABASE_SERVICE_ROLE_KEY are provided by Supabase.

type Any = any;

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-job-secret, x-job-wait, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};
const jobJson = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

// Replaced with the git commit when the function is copied for deployment.
const JOB_BUILD = "__BUILD__";

// ---------- The research pipeline and the website rule, inlined from the app source ----------
// ===== inlined from src/lib/website.ts =====
// A company website entered by a person: "example.com", "https://www.Example.com/about?x=1" -> "example.com".
// Returns undefined for an empty value and null for something that cannot be a company website.
// The same rule is applied again inside the research function, which never trusts the page.
function normalizeWebsite(input: string | null | undefined): string | undefined | null {
  const raw = (input ?? "").trim();
  if (!raw) return undefined;
  if (/\s/.test(raw)) return null;
  let host = raw.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "");
  host = host.split(/[/?#]/)[0].replace(/:\d+$/, "").toLowerCase().replace(/^www\./, "").replace(/\.$/, "");
  if (!host || host.length > 253) return null;
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(host)) return null; // needs a dot, letters/digits/hyphens only
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return null; // IP address
  if (host === "localhost" || host.endsWith(".local") || host.endsWith(".internal")) return null;
  return host;
}
