// ---------- Configuration ----------
const JOB_DOMAIN = "toptal.com"; // hard constraint: reports are only ever sent to a toptal.com address
const jobWindowMs = () => Number(Deno.env.get("JOB_WINDOW_MS")) || 40_000; // start new research calls for this long per slice
const jobHardMs = () => Number(Deno.env.get("JOB_HARD_MS")) || 130_000; // then stop waiting for calls still running
const JOB_LOCK_MS = 170_000;
const JOB_MAX_ATTEMPTS = 30; // slices (and retried slices) before a job gives up
const JOB_MAX_AGE_MS = 30 * 60_000;
const JOB_STALL_MS = 90_000; // a running job idle this long (and unlocked) is restarted by `resume`
const JOB_MAX_ACTIVE = 2;
const JOB_MAX_PER_DAY = 10;
const JOB_RETENTION_DAYS = 30;

// ---------- Small helpers ----------
const jobEnv = (k: string) => Deno.env.get(k) ?? "";
const jobEmailOk = (e: unknown): e is string => typeof e === "string" && new RegExp(`^[^@\\s]+@${JOB_DOMAIN.replace(".", "\\.")}$`, "i").test(e);

function jobSameSecret(a: string, b: string): boolean {
  if (!a || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}
const jobIsInternal = (req: Request) => jobSameSecret(req.headers.get("x-job-secret") ?? "", jobEnv("JOB_SECRET"));

async function jobHash(text: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

const jobEsc = (s: string) => s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c] as string);

// ---------- Database (PostgREST with the service role) ----------
async function jobDb(method: string, path: string, body?: unknown, prefer?: string): Promise<Any> {
  const key = jobEnv("SUPABASE_SERVICE_ROLE_KEY");
  const res = await fetch(`${jobEnv("SUPABASE_URL")}/rest/v1/${path}`, {
    method,
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
      ...(prefer ? { Prefer: prefer } : {}),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
    signal: AbortSignal.timeout(20_000),
  });
  if (!res.ok) throw new Error(`database ${method} ${path.split("?")[0]} failed (${res.status}): ${(await res.text()).slice(0, 200)}`);
  const text = await res.text();
  return text ? JSON.parse(text) : null;
}
const jobPatch = (id: string, fields: Record<string, unknown>) =>
  jobDb("PATCH", `client_insight_jobs?id=eq.${id}`, { ...fields, updated_at: new Date().toISOString() });

// ---------- Calling the research function as the person who asked ----------
async function jobCallStep(body: Record<string, unknown>, email: string): Promise<Any> {
  const key = jobEnv("SUPABASE_SERVICE_ROLE_KEY");
  const res = await fetch(`${jobEnv("SUPABASE_URL")}/functions/v1/gemini-research`, {
    method: "POST",
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
      "x-job-secret": jobEnv("JOB_SECRET"),
      "x-job-user": email,
    },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(jobHardMs() + 10_000),
  });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw Object.assign(new Error(data?.error || `research step failed (${res.status})`), { status: res.status });
  if (data?.error) throw new Error(data.error);
  return data;
}

async function jobTriggerRun(id: string): Promise<void> {
  const key = jobEnv("SUPABASE_SERVICE_ROLE_KEY");
  try {
    const res = await fetch(`${jobEnv("SUPABASE_URL")}/functions/v1/client-insights-job`, {
      method: "POST",
      headers: { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json", "x-job-secret": jobEnv("JOB_SECRET") },
      body: JSON.stringify({ action: "run", id }),
      signal: AbortSignal.timeout(15_000),
    });
    await res.body?.cancel();
  } catch (e) {
    console.error("could not start the next slice (the cron resume will pick the job up):", e instanceof Error ? e.message : e);
  }
}

// ---------- Email (Google Apps Script web app under the shared Toptal MC Hub mailbox) ----------
async function jobSendEmail(to: string, subject: string, html: string): Promise<boolean> {
  // The recipient rule is checked again here even though the database already enforces it.
  if (!jobEmailOk(to)) {
    console.error("refusing to email a non-toptal.com address");
    return false;
  }
  const url = jobEnv("APPS_SCRIPT_URL");
  if (!url) {
    console.error("APPS_SCRIPT_URL is not set; no email sent");
    return false;
  }
  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({ secret: jobEnv("APPS_SCRIPT_SECRET"), to: to.toLowerCase(), subject, html }),
      redirect: "follow",
      signal: AbortSignal.timeout(30_000),
    });
    const out = await res.json().catch(() => null);
    if (!res.ok || out?.ok !== true) {
      console.error("email was not accepted:", res.status, out?.error ?? "");
      return false;
    }
    return true;
  } catch (e) {
    console.error("email failed:", e instanceof Error ? e.message : e);
    return false;
  }
}

const jobAppUrl = () => (jobEnv("APP_URL") || "https://mc-hub.toptal.tech").replace(/\/+$/, "");

function jobReadyEmail(job: Any) {
  const link = `${jobAppUrl()}/client-insights?report=${encodeURIComponent(job.id)}`;
  const expires = new Date(job.expires_at ?? Date.now() + JOB_RETENTION_DAYS * 86_400_000).toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
  return {
    subject: `Your Client Insights report for ${job.company} is ready`,
    html:
      `<p>Your Client Insights report for <strong>${jobEsc(job.company)}</strong> is ready.</p>` +
      `<p><a href="${link}">Open the report</a></p>` +
      `<p style="color:#555">This is AI-generated research. Statements are checked against cited sources by automated rules and a second model pass, ` +
      `but the checks are not exhaustive and the report may contain errors. Verify before client use.</p>` +
      `<p style="color:#555">Only you can open this link (sign in with your Toptal account). The report is kept until ${jobEsc(expires)}.</p>`,
  };
}

function jobFailedEmail(job: Any, reason: string) {
  return {
    subject: `Your Client Insights report for ${job.company} could not be completed`,
    html:
      `<p>The Client Insights research for <strong>${jobEsc(job.company)}</strong> could not be completed.</p>` +
      `<p style="color:#555">${jobEsc(reason)}</p>` +
      `<p>You can try again from <a href="${jobAppUrl()}/client-insights">Client Insights</a>. ` +
      `If it keeps failing, adding the company website often helps.</p>`,
  };
}

// Email is optional: without APPS_SCRIPT_URL the report is simply saved and shown under "Your recent reports".
const jobEmailEnabled = () => !!jobEnv("APPS_SCRIPT_URL");

async function jobNotify(job: Any, mail: { subject: string; html: string }) {
  if (job.emailed_at || !jobEmailEnabled()) return;
  if (await jobSendEmail(job.email, mail.subject, mail.html)) {
    await jobPatch(job.id, { emailed_at: new Date().toISOString() }).catch(() => {});
  }
}

// ---------- Finishing a job ----------
async function jobFinishFailed(job: Any, reason: string) {
  const message = reason.slice(0, 300);
  await jobPatch(job.id, { status: "failed", error: message, progress: null, lock_until: null, finished_at: new Date().toISOString() });
  await jobDb("DELETE", `client_insight_steps?job_id=eq.${job.id}`).catch(() => {});
  await jobNotify({ ...job, emailed_at: null }, jobFailedEmail(job, message));
}

async function jobFinishDone(job: Any, result: Any) {
  const finished = new Date();
  await jobDb("POST", "client_insight_reports?on_conflict=job_id", { job_id: job.id, result }, "resolution=merge-duplicates");
  await jobPatch(job.id, { status: "done", error: null, progress: null, lock_until: null, finished_at: finished.toISOString() });
  await jobDb("DELETE", `client_insight_steps?job_id=eq.${job.id}`).catch(() => {});
  await jobNotify({ ...job, emailed_at: null }, jobReadyEmail(job));
}

// ---------- One slice ----------
async function jobRunSlice(id: string): Promise<{ outcome: string }> {
  const rows = await jobDb("GET", `client_insight_jobs?id=eq.${id}&select=*`);
  const job = rows?.[0];
  if (!job || job.status !== "running") return { outcome: "not-running" };

  if (job.attempts >= JOB_MAX_ATTEMPTS || Date.now() - Date.parse(job.created_at) > JOB_MAX_AGE_MS) {
    await jobFinishFailed(job, "The research took too long to finish.");
    return { outcome: "failed-timeout" };
  }

  // Take the lock; the filter makes this atomic, so two runners cannot work on the same job.
  const now = new Date();
  const locked = await jobDb(
    "PATCH",
    `client_insight_jobs?id=eq.${id}&status=eq.running&or=(lock_until.is.null,lock_until.lt.${now.toISOString()})`,
    { lock_until: new Date(now.getTime() + JOB_LOCK_MS).toISOString(), attempts: job.attempts + 1, updated_at: now.toISOString() },
    "return=representation",
  );
  if (!locked?.length) return { outcome: "locked" };

  // Replay the pipeline against the journal.
  const journal = new Map<string, Any>();
  for (const row of (await jobDb("GET", `client_insight_steps?job_id=eq.${id}&select=key,response`)) ?? []) journal.set(row.key, row.response);

  const t0 = Date.now();
  const consumed = new Map<string, number>(); // how many journalled answers each distinct request has used in this replay
  let inflight = 0;
  let suspended = false;
  let wake: () => void = () => {};
  const suspendSignal = new Promise<void>((r) => (wake = r));
  const hardTimer = setTimeout(() => ((suspended = true), wake()), jobHardMs());
  let lastChips: ProgressChip[] = [];

  const call = async (body: Record<string, unknown>) => {
    const base = await jobHash(JSON.stringify(body));
    const key = `${base}#${consumed.get(base) ?? 0}`;
    if (journal.has(key)) {
      consumed.set(base, (consumed.get(base) ?? 0) + 1);
      return structuredClone(journal.get(key));
    }
    if (suspended || Date.now() - t0 > jobWindowMs()) {
      suspended = true;
      if (inflight === 0) wake();
      return new Promise<never>(() => {}); // park this branch of the pipeline; the next slice replays it
    }
    inflight++;
    try {
      const response = await jobCallStep(body, job.email);
      journal.set(key, response);
      consumed.set(base, (consumed.get(base) ?? 0) + 1);
      await jobDb("POST", "client_insight_steps?on_conflict=job_id,key", { job_id: id, key, response }, "resolution=merge-duplicates").catch((e) =>
        console.error("could not journal a step:", e instanceof Error ? e.message : e),
      );
      return structuredClone(response);
    } finally {
      inflight--;
      if (suspended && inflight === 0) wake();
    }
  };

  const run = runResearch({
    call,
    companyName: job.company,
    companyWebsite: job.website ?? undefined,
    deepResearch: !!job.deep_research,
    onProgress: (chips) => (lastChips = chips),
  }).then(
    (result) => ({ kind: "done" as const, result }),
    (error) => ({ kind: "error" as const, error }),
  );
  const first = await Promise.race([run, suspendSignal.then(() => ({ kind: "suspend" as const }))]);
  clearTimeout(hardTimer);

  if (first.kind === "done") {
    await jobFinishDone(job, first.result);
    return { outcome: "done" };
  }
  if (first.kind === "error") {
    const e = first.error as Any;
    const message = e instanceof Error ? e.message : String(e);
    if (retryable(e) && job.attempts + 1 < JOB_MAX_ATTEMPTS) {
      // Transient (gateway, rate limit): unlock and let the next resume try again.
      await jobPatch(id, { lock_until: null, progress: "Waiting to retry" });
      return { outcome: "retry" };
    }
    await jobFinishFailed(job, message);
    return { outcome: "failed" };
  }

  const done = lastChips.filter((c) => c.status === "done" || c.status === "retried").length;
  await jobPatch(id, { lock_until: null, progress: `${done} of ${lastChips.length || "?"} stages done` });
  await jobTriggerRun(id);
  return { outcome: "continued" };
}

// ---------- Routes ----------
async function jobStart(req: Request, body: Any): Promise<Response> {
  const supabaseUrl = jobEnv("SUPABASE_URL");
  const auth = req.headers.get("authorization") ?? "";
  if (!supabaseUrl || !/^bearer\s+\S+/i.test(auth)) return jobJson({ error: "Please sign in with your Toptal Google account." }, 401);

  // Who is asking comes from the token, never from the request body.
  let user: Any;
  try {
    const res = await fetch(`${supabaseUrl}/auth/v1/user`, {
      headers: { apikey: req.headers.get("apikey") ?? jobEnv("SUPABASE_ANON_KEY"), Authorization: auth },
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) {
      await res.body?.cancel();
      return jobJson({ error: "Your sign-in has expired. Sign out, sign back in, and try again." }, 401);
    }
    user = await res.json();
  } catch {
    return jobJson({ error: "Could not verify your sign-in. Try again in a moment." }, 503);
  }
  const email = String(user?.email ?? "").toLowerCase();
  if (!user?.id || !jobEmailOk(email)) return jobJson({ error: `Emailed reports are only available to @${JOB_DOMAIN} accounts.` }, 403);

  const company = typeof body?.companyName === "string" ? body.companyName.trim() : "";
  if (!company || company.length > 200) return jobJson({ error: "companyName is required (max 200 characters)" }, 400);
  let website: string | undefined;
  if (typeof body?.companyWebsite === "string" && body.companyWebsite.trim()) {
    const w = normalizeWebsite(body.companyWebsite);
    if (w === null) return jobJson({ error: "companyWebsite must be a website such as example.com" }, 400);
    website = w;
  }

  const active = (await jobDb("GET", `client_insight_jobs?user_id=eq.${user.id}&status=eq.running&select=id`)) ?? [];
  if (active.length >= JOB_MAX_ACTIVE) return jobJson({ error: `You already have ${JOB_MAX_ACTIVE} reports running. Wait for one to finish.` }, 429);
  const since = new Date(Date.now() - 86_400_000).toISOString();
  const recent = (await jobDb("GET", `client_insight_jobs?user_id=eq.${user.id}&created_at=gte.${since}&select=id`)) ?? [];
  if (recent.length >= JOB_MAX_PER_DAY) return jobJson({ error: `You can email up to ${JOB_MAX_PER_DAY} reports a day. Try again tomorrow.` }, 429);

  const created = await jobDb(
    "POST",
    "client_insight_jobs",
    {
      user_id: user.id,
      email,
      company,
      website: website ?? null,
      deep_research: body?.deepResearch !== false,
      expires_at: new Date(Date.now() + JOB_RETENTION_DAYS * 86_400_000).toISOString(),
    },
    "return=representation",
  );
  const job = created?.[0];
  if (!job) return jobJson({ error: "Could not start the report." }, 500);
  await jobTriggerRun(job.id);
  return jobJson({ id: job.id, email, expiresAt: job.expires_at }, 202);
}

async function jobResume(): Promise<Response> {
  const now = Date.now();
  const stalledBefore = new Date(now - JOB_STALL_MS).toISOString();
  const lockBefore = new Date(now).toISOString();
  const stalled =
    (await jobDb("GET", `client_insight_jobs?status=eq.running&updated_at=lt.${stalledBefore}&or=(lock_until.is.null,lock_until.lt.${lockBefore})&select=id&limit=20`)) ?? [];
  for (const j of stalled) await jobTriggerRun(j.id);

  // Reports that finished but whose email was not accepted: try again for an hour (only when email is set up).
  const hourAgo = new Date(now - 3_600_000).toISOString();
  const unsent = !jobEmailEnabled() ? [] : (await jobDb("GET", `client_insight_jobs?status=in.(done,failed)&emailed_at=is.null&finished_at=gte.${hourAgo}&select=*&limit=20`)) ?? [];
  for (const j of unsent) {
    await jobNotify(j, j.status === "done" ? jobReadyEmail(j) : jobFailedEmail(j, j.error || "The research could not be completed."));
  }

  // Reports are kept for 30 days.
  await jobDb("DELETE", `client_insight_jobs?expires_at=lt.${new Date(now).toISOString()}`).catch(() => {});
  return jobJson({ resumed: stalled.length, emailRetried: unsent.length });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
  if (req.method !== "POST") return jobJson({ error: "Use POST" }, 405);

  let body: Any;
  try {
    body = await req.json();
  } catch {
    return jobJson({ error: "Request body must be JSON" }, 400);
  }

  try {
    if (body?.action === "start") return await jobStart(req, body);

    if (body?.action === "run" || body?.action === "resume") {
      if (!jobIsInternal(req)) return jobJson({ error: "Not authorised." }, 401);
      if (body.action === "resume") return await jobResume();
      const id = typeof body?.id === "string" && /^[0-9a-f-]{36}$/i.test(body.id) ? body.id : "";
      if (!id) return jobJson({ error: "id is required" }, 400);
      const work = jobRunSlice(id).catch(async (e) => {
        console.error("slice failed:", e instanceof Error ? e.message : e);
        await jobPatch(id, { lock_until: null }).catch(() => {});
        return { outcome: "error" };
      });
      // In the Supabase runtime the slice keeps running after the 202 is returned; a caller can ask to wait instead.
      const runtime = (globalThis as Any).EdgeRuntime;
      if (runtime?.waitUntil && req.headers.get("x-job-wait") !== "1") {
        runtime.waitUntil(work);
        return jobJson({ accepted: true }, 202);
      }
      return jobJson(await work);
    }
    return jobJson({ error: "Unknown action" }, 400);
  } catch (e) {
    console.error("job error:", e);
    return jobJson({ error: e instanceof Error ? e.message : "Unknown error" }, 500);
  }
});
